#include <iostream>
#include <algorithm>
using namespace std;

int total(int a, int s) {
    if (s <= 0)
        return 0;
    if (a == 0)
        return s / 2;

    long long distance = a >= 0 ? a : -(long long)a;
    return static_cast<int>(min<long long>(distance, s));
}

int main() {
    int a, b, s;
    cin >> a >> b >> s;

    if (s < b) {
        cout << "NO";
    } else {
        int count = total(a, s) + total(b, s);
        cout << (count == s ? "YES" : "NO");
    }

    return 0;
}

